import SwiftUI

/// The la-carte mark: a portrait card crossed by the forgetting curve, drawn as one thick line. Inside the card the
/// line is cut out of it (even-odd); outside the card it's the accent pink, the mark's one standout colour. Built from
/// shapes in a 100×100 box (`LogoGeometry`, numbers generated by `docs/design/brand/render.py`), so it scales to any
/// size and takes the theme's tokens.
///
/// `progress` draws it in (0 = nothing, 1 = the full mark) and is animatable: the card settles in, then the curve is
/// drawn from its first peak to its end. Used by `LaCarteLaunchMark`, `LaCarteLoadingMark` and in
/// `matchedGeometryEffect`.
public struct LaCarteLogo: View, Animatable {
  nonisolated public var progress: Double

  public init(progress: Double = 1) {
    self.progress = progress
  }

  /// `nonisolated`: `Animatable` isn't main-actor isolated, but `View` makes the struct `@MainActor`.
  nonisolated public var animatableData: Double {
    get { progress }
    set { progress = newValue }
  }

  public var body: some View {
    let geometry = LogoGeometry(progress: progress)
    ZStack {
      UnitShape(path: geometry.cardBody)
        .fill(Theme.ink)
        .opacity(geometry.cardOpacity)
      UnitShape(path: geometry.lineOutside)
        .fill(Theme.accent)
    }
    .aspectRatio(1, contentMode: .fit)
    .accessibilityElement()
    .accessibilityLabel("la carte")
    .accessibilityAddTraits(.isImage)
  }
}

/// The logo's shapes in a 100×100 box, as a pure function of `progress` (tested in `LaCarteLogoTests`).
/// The constants (card, curve, stroke, reset bar) are in the generated `LaCarteLogoGeometry.swift`.
struct LogoGeometry: Equatable {
  /// 0–0.05: the card fades and settles in (≈135 ms of `logoDrawIn`, so the launch mark's tilt plays on a solid card).
  /// 0.3–1: the curve is drawn.
  static let cardPhase = 0.0...0.05
  static let linePhase = 0.3...1.0

  var cardOpacity: Double
  var cardScale: Double
  /// How much of the curve is drawn, 0–1 of its length.
  var lineTrim: Double

  init(progress: Double) {
    let p = min(max(progress, 0), 1)
    let appear = Self.ease(p, Self.cardPhase)
    cardOpacity = appear
    cardScale = 0.94 + 0.06 * appear
    lineTrim = Self.linearStep(p, Self.linePhase)
  }

  /// Smoothstep of `p` over `range`.
  static func ease(_ p: Double, _ range: ClosedRange<Double>) -> Double {
    let t = linearStep(p, range)
    return t * t * (3 - 2 * t)
  }

  /// The line is drawn at an even pace: the view's animation curve already eases the whole draw-in.
  static func linearStep(_ p: Double, _ range: ClosedRange<Double>) -> Double {
    min(max((p - range.lowerBound) / (range.upperBound - range.lowerBound), 0), 1)
  }

  /// The card minus the line: the line is cut out where it crosses the card.
  var cardBody: Path {
    guard cardOpacity > 0 else { return Path() }
    let center = CGPoint(x: Self.card.midX, y: Self.card.midY)
    let settle = CGAffineTransform(translationX: center.x, y: center.y)
      .scaledBy(x: cardScale, y: cardScale)
      .translatedBy(x: -center.x, y: -center.y)
    let card = Path(roundedRect: Self.card, cornerRadius: Self.cardRadius).applying(settle)
    let line = line
    return line.isEmpty ? card : card.subtracting(line)
  }

  /// The line outside the card (pink). Measured against the settled card, so it never changes once drawn.
  var lineOutside: Path {
    let line = line
    guard !line.isEmpty else { return Path() }
    return line.subtracting(Path(roundedRect: Self.card, cornerRadius: Self.cardRadius))
  }

  /// The drawn part of the line: decay 1, then the reset bar rising from its foot, then the rest, each stroked with
  /// round caps. The reset's own centreline segment is left out: the bar covers it exactly (checked in render.py's
  /// shapes), and a stroke climbing inside a half-grown bar reads as a blob.
  var line: Path {
    guard lineTrim > 0 else { return Path() }
    let reset = Self.resetRange
    let start = Self.centreline.trimmedPath(from: 0, to: min(lineTrim, reset.lowerBound))
    var line = Self.stroked(start, width: Self.startWidth(lineTrim))
    let rise = Self.linearStep(lineTrim, reset)
    if rise > 0 {
      line = line.union(Self.rising(Self.bar, radius: Self.barRadius, rise: rise))
        .union(Self.rising(Self.barFoot, radius: Self.barFootRadius, rise: rise, from: Self.bar))
    }
    if lineTrim > reset.upperBound {
      let decay2 = Self.stroked(Self.centreline.trimmedPath(from: reset.upperBound, to: lineTrim))
      if !decay2.isEmpty {
        line = line.union(decay2)
      }
    }
    return line
  }

  /// The stroked centreline, or an empty path when the trim is too short to stroke: a degenerate path isn't `isEmpty`,
  /// and boolean ops with it misbehave (`degenerate.subtracting(card)` returns the whole card).
  static func stroked(_ path: Path, width: CGFloat = strokeWidth) -> Path {
    let stroke = path.strokedPath(StrokeStyle(lineWidth: width, lineCap: .round, lineJoin: .round))
    return stroke.boundingRect.isEmpty ? Path() : stroke
  }

  /// The line's width at its start: it grows from 0 to the full stroke over its first stroke-width of length. A round
  /// cap makes even a zero-length stroke a full dot, so at full width the line's first frame (and the loading mark's
  /// last erased one) would pop a dot in or out.
  static func startWidth(_ trim: Double) -> CGFloat {
    strokeWidth * min(1, CGFloat(trim) * centrelineLength / strokeWidth)
  }

  static let centreline: Path = Path { $0.addLines(curve) }

  static let centrelineLength: CGFloat = zip(curve, curve.dropFirst()).map { hypot($1.x - $0.x, $1.y - $0.y) }
    .reduce(0, +)

  /// The share of the centreline's length where the reset runs (from decay 1's low point up to the peak).
  static let resetRange: ClosedRange<Double> = {
    let lengths = zip(curve, curve.dropFirst()).map { hypot($1.x - $0.x, $1.y - $0.y) }
    let total = lengths.reduce(0, +)
    let start = lengths.prefix(resetTop - 1).reduce(0, +)
    return Double(start / total)...Double((start + lengths[resetTop - 1]) / total)
  }()

  /// `rect` cut to what the bar shows at `rise` (0–1): the bar grows up from its foot (`from`'s bottom edge).
  static func rising(_ rect: CGRect, radius: CGFloat, rise: Double, from bar: CGRect? = nil) -> Path {
    let bar = bar ?? rect
    let top = max(rect.minY, bar.maxY - bar.height * rise)
    let shown = CGRect(x: rect.minX, y: top, width: rect.width, height: rect.maxY - top)
    return Path(roundedRect: shown, cornerRadius: min(radius, shown.height / 2, shown.width / 2))
  }
}

/// Draws a path from the 100×100 logo box, scaled to fit and centered in the given rect.
private struct UnitShape: Shape {
  let path: Path

  func path(in rect: CGRect) -> Path {
    let side = min(rect.width, rect.height)
    let transform = CGAffineTransform(translationX: rect.midX - side / 2, y: rect.midY - side / 2)
      .scaledBy(x: side / 100, y: side / 100)
    return path.applying(transform)
  }
}

/// The logo drawing itself in once, e.g. on the "All caught up" screen. The card arrives tilted in 3D about its
/// diagonal and lays itself flat (`logoTilt`) while the curve starts drawing (`logoDrawIn`); the line is in the
/// card's plane, so the mark moves as one object. With Reduce Motion it's the finished mark, static. Never shown
/// at app launch: nothing may delay the first card.
public struct LaCarteLaunchMark: View {
  /// The tilt the card arrives with, about the bottom-left → top-right diagonal.
  static let tilt = Angle.degrees(40)
  static let tiltAxis: (x: CGFloat, y: CGFloat, z: CGFloat) = (1, 1, 0)

  @Environment(\.accessibilityReduceMotion) private var reduceMotion
  @State private var shown = false

  public init() {}

  public var body: some View {
    if reduceMotion {
      LaCarteLogo()
    } else {
      LaCarteLogo(progress: shown ? 1 : 0)
        .animation(Theme.Motion.logoTilt) { $0.launchTilt(shown ? 0 : 1) }
        .onAppear {
          withAnimation(Theme.Motion.logoDrawIn) { shown = true }
        }
    }
  }

  /// The mark `time` seconds into its draw-in, on the same curves as the live one (for renders and reviews).
  static func frame(at time: Double) -> some View {
    func value(_ timing: (curve: UnitCurve, duration: Double)) -> Double {
      timing.curve.value(at: min(max(time / timing.duration, 0), 1))
    }
    return LaCarteLogo(progress: value(Theme.Motion.logoDrawInCurve))
      .launchTilt(1 - value(Theme.Motion.logoTiltCurve))
  }
}

extension View {
  /// `amount` of the launch mark's tilt: 1 = arriving, 0 = flat. Logo and line turn together, as one card.
  fileprivate func launchTilt(_ amount: Double) -> some View {
    rotation3DEffect(
      .degrees(LaCarteLaunchMark.tilt.degrees * amount), axis: LaCarteLaunchMark.tiltAxis, perspective: 0.6
    )
  }
}

/// The logo as a loading indicator: the curve is drawn and erased over the card, slowly.
/// With Reduce Motion the whole mark dims and brightens instead (no movement).
public struct LaCarteLoadingMark: View {
  @Environment(\.accessibilityReduceMotion) private var reduceMotion

  public init() {}

  public var body: some View {
    Group {
      if reduceMotion {
        LaCarteLogo()
          .phaseAnimator([1.0, 0.4]) { logo, opacity in
            logo.opacity(opacity)
          } animation: { _ in Theme.Motion.loadingPulse }
      } else {
        // `linePhase.lowerBound` is the card alone (see `LogoGeometry`).
        PhaseAnimator([1.0, LogoGeometry.linePhase.lowerBound]) { progress in
          LaCarteLogo(progress: progress)
        } animation: { _ in Theme.Motion.loadingPulse }
      }
    }
    .accessibilityLabel("Loading")
  }
}

